    (
        DT6.DT6_DOC in ('000002165', '000002166', '000002167', '000002168', '000002169', '000002170', '000002171', '000002172', '000002173', '000002174', '000002175', '000002176', '000002179', '000002180', '000002181', '000002182', '000002184', '000002185', '000002186', '000002187', '000002188', '000002189', '000002190', '000002195', '000002196', '000002203', '000002208', '000002209', '000002210', '000002211', '000002212', '000002213', '000002214', '000002215', '000002216', '000002217', '000002218', '000002219', '000002221', '000002222', '000002227', '000002228', '000002229', '000002230', '000002231', '000002232', '000002233', '000002234', '000002235', '000002246', '000002247', '000002249', '000002250', '000002251', '000002252', '000002253', '000002254', '000002255', '000002256', '000002262', '000002263', '000002264', '000002265', '000002266', '000002267', '000002268', '000002269', '000002270', '000002271', '000002294', '000002295', '000002296', '000002297', '000002298', '000002299', '000002300', '000002301', '000002302', '000002303', '000002304', '000002305', '000002306', '000002307', '000002314', '000002323', '000052702', '000052703', '000052704', '000052706', '000052707', '000052708', '000052709', '000052710', '000052711', '000052712', '000052713', '000052714', '000052715', '000052716', '000052717', '000052718', '000052719', '000052720', '000052721', '000052722', '000052723', '000052725', '000052726', '000052727', '000052728', '000052729', '000052730', '000052735', '000052736', '000052737', '000052738', '000052739', '000052740', '000052741', '000052742', '000052743', '000052744', '000052745', '000052746', '000052747', '000052748', '000052749', '000052750', '000052751', '000052752', '000052753', '000052754', '000052755', '000052756', '000052757', '000052758', '000052759', '000052760', '000052761', '000052762', '000052764', '000052765', '000052766', '000052767', '000052768', '000052769', '000052770', '000052778', '000052779', '000052780', '000052781', '000052784', '000052785', '000052786', '000052787', '000052788', '000052789', '000052790', '000052791', '000052792', '000052793', '000052794', '000052795', '000052796', '000052797', '000052798', '000052799', '000052800', '000052802', '000052803', '000052804', '000052805', '000052806', '000052807', '000052808', '000052809', '000052810', '000052811', '000052812', '000052813', '000052814', '000052815', '000052816', '000052817', '000052818', '000052819', '000052820', '000052821', '000052822', '000052823', '000052824', '000052825', '000052826', '000052827', '000052828', '000052829', '000052830', '000052831', '000052832', '000052833', '000052834', '000052835', '000052836', '000052837', '000052838', '000052839', '000052840', '000052841', '000052842', '000052843', '000052844', '000052845', '000052846', '000052847', '000052848', '000052849', '000052851', '000052852', '000052853', '000052854', '000052855', '000052856', '000052857', '000052858', '000052859', '000052860', '000052861', '000052862', '000052863', '000052864', '000052865', '000052866', '000052867', '000052868', '000052869', '000052870', '000052871', '000052872', '000052873', '000052874', '000052875', '000052876', '000052877', '000052878', '000052879', '000052880', '000052881', '000052882', '000052883', '000052884', '000052885', '000052886', '000052888', '000052889', '000052890', '000052891', '000052892', '000052893', '000052894', '000052895', '000052896', '000052897', '000052899', '000052900', '000052901', '000052903', '000052904', '000052905', '000052906', '000052907', '000052909', '000052910', '000052911', '000052912', '000052913', '000052914', '000052915', '000052916', '000052917', '000052918', '000052919', '000052920', '000052921', '000052922', '000052923', '000052924', '000052925', '000052926', '000052927', '000052928', '000052929', '000052930', '000052931', '000052932', '000052933', '000052934', '000052935', '000052936', '000052937', '000052938', '000052939', '000052940', '000052941', '000052942', '000052944', '000052946'